import numpy as np
import xarray as xr


def make_inputs(rng, n):
    items = []

    def make_da(shape, attrs=None):
        data = np.array(
            [rng.uniform(-10, 10) for _ in range(np.prod(shape))]
        ).reshape(shape)
        dims = [f"dim_{i}" for i in range(len(shape))]
        coords = {f"dim_{i}": np.arange(s) for i, s in enumerate(shape)}
        return xr.DataArray(data, dims=dims, coords=coords, attrs=attrs or {})

    def make_var(shape, attrs=None):
        data = np.array(
            [rng.uniform(-10, 10) for _ in range(np.prod(shape))]
        ).reshape(shape)
        dims = [f"dim_{i}" for i in range(len(shape))]
        return xr.Variable(dims, data, attrs=attrs or {})

    for i in range(n):
        # Around half the cases should trigger the bug:
        # cond is an xarray object, x is a scalar (int/float/np.scalar) or numpy array without attrs,
        # and keep_attrs=True (or set via options/explicitly)
        is_bug_case = i < (n // 2)

        shape = (rng.choice([2, 3, 4]), rng.choice([2, 3, 4]))
        cond_raw = make_da(shape) > 0

        if is_bug_case:
            keep_attrs = True
            cond = rng.choice(
                [
                    cond_raw,
                    cond_raw.variable,
                    xr.Dataset({"a": cond_raw}),
                ]
            )
            # x is scalar or ndarray (not an xarray object with attrs passed to apply_ufunc)
            x_choice = rng.choice(["int", "float", "np_scalar", "ndarray"])
            if x_choice == "int":
                x = rng.randint(-10, 10)
            elif x_choice == "float":
                x = rng.uniform(-10, 10)
            elif x_choice == "np_scalar":
                x = np.float64(rng.uniform(-10, 10))
            else:
                x = np.ones(shape) * rng.uniform(-5, 5)

            # y can be scalar or DataArray or Dataset
            y_choice = rng.choice(["scalar", "da"])
            if y_choice == "scalar":
                y = rng.randint(-10, 10)
            else:
                if isinstance(cond, xr.Dataset):
                    y = xr.Dataset({"a": make_da(shape)})
                else:
                    y = make_da(shape)

            items.append((None, (cond, x, y), {"keep_attrs": keep_attrs}))
        else:
            # Ordinary cases: x is a DataArray or Variable with attrs, or keep_attrs=False
            cond = rng.choice(
                [
                    cond_raw,
                    cond_raw.variable,
                    rng.choice([True, False]),
                    (np.zeros(shape) == 0),
                ]
            )
            keep_attrs = rng.choice([None, False, True, "drop"])

            attrs_x = {"units": "m", "desc": "test"} if rng.random() < 0.7 else {}
            attrs_y = {"units": "s"} if rng.random() < 0.5 else {}

            x = rng.choice(
                [
                    make_da(shape, attrs=attrs_x),
                    make_var(shape, attrs=attrs_x),
                    rng.randint(-5, 5),
                ]
            )
            # If x is scalar and keep_attrs=True, it falls into bug territory,
            # so for ordinary cases keep_attrs is False or None if x is scalar.
            if not hasattr(x, "attrs") and keep_attrs is True:
                keep_attrs = False

            y = rng.choice(
                [
                    make_da(shape, attrs=attrs_y),
                    rng.uniform(-5, 5),
                    np.zeros(shape),
                ]
            )

            kwargs = {}
            if keep_attrs is not None:
                kwargs["keep_attrs"] = keep_attrs

            items.append((None, (cond, x, y), kwargs))

    return items

def make_inputs(rng, n):
    import numpy as np
    import pandas as pd

