    estimator_class = getattr(module, "BaseEstimator", target_class)

    dtypes_list = [
        np.float32,
        np.float64,
        np.int32,
        np.int64,
        "category",
    ]

    for i in range(n):
        receiver = estimator_class()

        # Decide whether to test the new cast_to_ndarray parameter
        is_cast_case = i % 2 == 1

        n_samples = rng.randint(5, 20)
        n_features = rng.randint(1, 5)

