                if dt == "category":
                    cats = ["a", "b", "c"]
                    vals = [rng.choice(cats) for _ in range(n_samples)]
                    data[col_name] = pd.Categorical(vals)
                elif np.issubdtype(dt, np.integer):
                    data[col_name] = np.array(
                        [rng.randint(0, 100) for _ in range(n_samples)], dtype=dt
                    )
                else:
                    data[col_name] = np.array(
                        [rng.uniform(-10.0, 10.0) for _ in range(n_samples)], dtype=dt
                    )
            X = pd.DataFrame(data)
        else:
            dt = rng.choice([np.float32, np.float64, np.int32, np.int64])
            X = np.array(
                [[rng.uniform(-10.0, 10.0) for _ in range(n_features)] for _ in range(n_samples)],
                dtype=dt,
            )

        kwargs = {}
        if is_cast_case:
            kwargs["cast_to_ndarray"] = rng.choice([True, False])

        reset = rng.choice([True, False])
        kwargs["reset"] = reset

        mode = rng.choice(["X_only", "y_only", "both"])
        y_val = np.array([rng.randint(0, 2) for _ in range(n_samples)], dtype=np.int32)

        if mode == "X_only":
            X_arg = X
            # Note: y must be None or 'no_validation', never a DataFrame
            y_arg = rng.choice([None, "no_validation"])
        elif mode == "y_only":
            X_arg = "no_validation"
            y_arg = y_val
        else:
            X_arg = X
            y_arg = y_val
            if rng.choice([True, False]):
                kwargs["validate_separately"] = ({}, {})

        # If reset=False and testing X, receiver needs n_features_in_ set
        if not reset and not (isinstance(X_arg, str) and X_arg == "no_validation"):
            receiver.n_features_in_ = n_features
            if hasattr(X_arg, "columns"):
                receiver.feature_names_in_ = np.array(X_arg.columns, dtype=object)

        # In check_array / check_X_y, categorical features will raise unless cast_to_ndarray=False
        if (not is_cast_case or kwargs.get("cast_to_ndarray", True)) and use_df:
            for col in X.columns:
                if X[col].dtype.name == "category":
                    X[col] = np.array(
                        [rng.uniform(0.0, 1.0) for _ in range(n_samples)], dtype=np.float64
                    )

        items.append((receiver, (X_arg, y_arg), kwargs))

    return items

