def make_inputs(rng, n):
    items = []

    dtypes_pool = [
        np.float32,
        np.float64,
        np.int32,
        np.int64,
        "category",
        "object",
        "string",
    ]

    for i in range(n):
        # Choose number of samples and features
        n_samples = rng.randint(1, 15)
        n_features = rng.randint(1, 8)

        # Decide input type: DataFrame vs ndarray vs sparse matrix
        # Focus about half on DataFrames (where upstream behavior changed significantly)
        is_df = (i % 2 == 1) or rng.random() < 0.2
        is_sparse = (not is_df) and (rng.random() < 0.25)

        # Decide mask behavior
        mask_scenario = rng.choice(["all_true", "all_false", "random", "mismatched_len"])
        if mask_scenario == "all_false":
            mask = np.zeros(n_features, dtype=bool)
        elif mask_scenario == "all_true":
            mask = np.ones(n_features, dtype=bool)
        elif mask_scenario == "mismatched_len":
            mismatched_features = n_features + rng.choice([-1, 1, 2])
            if mismatched_features <= 0:
                mismatched_features = n_features + 2
            mask = np.array([rng.choice([True, False]) for _ in range(mismatched_features)])
            if not mask.any():
                mask[0] = True
        else:
            mask = np.array([rng.choice([True, False]) for _ in range(n_features)])

        receiver = DummySelector(mask=mask)

        if is_df:
            # Generate pandas DataFrame with various column dtypes
            data_dict = {}
            for col_idx in range(n_features):
                col_dtype = rng.choice(dtypes_pool)
                col_name = f"col_{col_idx}"
                if col_dtype in [np.float32, np.float64]:
                    vals = np.array(
                        [rng.gauss(0, 1) for _ in range(n_samples)], dtype=col_dtype
                    )
                elif col_dtype in [np.int32, np.int64]:
                    vals = np.array(
                        [rng.randint(-10, 10) for _ in range(n_samples)], dtype=col_dtype
                    )
                elif col_dtype == "category":
                    cats = ["a", "b", "c", "d"]
                    vals = pd.Categorical([rng.choice(cats) for _ in range(n_samples)])
                elif col_dtype == "string":
                    vals = [rng.choice(["apple", "banana", "cherry"]) for _ in range(n_samples)]
                    vals = pd.Series(vals, dtype="string")
                else:  # object
                    vals = [rng.choice(["cat", 1, 2.5, None]) for _ in range(n_samples)]
                data_dict[col_name] = vals

            X = pd.DataFrame(data_dict)
        elif is_sparse:
            dense_data = np.array(
                [[rng.choice([0, 0, rng.random()]) for _ in range(n_features)] for _ in range(n_samples)],
                dtype=rng.choice([np.float32, np.float64]),
            )
            sparse_type = rng.choice([sparse.csr_matrix, sparse.csc_matrix])
            X = sparse_type(dense_data)
        else:
            dtype = rng.choice([np.float32, np.float64, np.int32, np.int64])
            X = np.array(
                [[rng.gauss(0, 1) for _ in range(n_features)] for _ in range(n_samples)],
                dtype=dtype,
            )

        items.append((receiver, (X,), {}))

    return items

