class DummySelector(module.SelectorMixin, BaseEstimator):
    def __init__(self, mask=None):
        self.mask = mask

    def fit(self, X, y=None):
        X = self._validate_data(X, accept_sparse=["csr", "csc"], dtype=None)
        if self.mask is None:
            self.mask_ = np.ones(X.shape[1], dtype=bool)
        else:
            self.mask_ = np.array(self.mask, dtype=bool)
        return self

    def _get_support_mask(self):
        return self.mask_


def make_inputs(rng, n):
    items = []

    for i in range(n):
        n_samples = rng.randint(2, 20)
        n_features = rng.randint(1, 6)

        # Support mask types: all True, all False, mixed, or single feature
        mask_type = rng.choice(["all_true", "all_false", "mixed", "single"])
        if mask_type == "all_true":
            mask = np.ones(n_features, dtype=bool)
        elif mask_type == "all_false":
            mask = np.zeros(n_features, dtype=bool)
        elif mask_type == "single":
            mask = np.zeros(n_features, dtype=bool)
            mask[rng.randint(0, n_features - 1)] = True
        else:
            mask = np.array([rng.choice([True, False]) for _ in range(n_features)])

        # Target the pandas dataframe preservation behavior about half the time
        use_pandas = (i % 2 == 1)

        if use_pandas:
            # Construct DataFrame with varied numeric / float / int types
            # (which _validate_data can validate even when converted to ndarray)
            cols = [f"col_{j}" for j in range(n_features)]
            data_dict = {}
            for col_name in cols:
                dtype_choice = rng.choice(
                    ["float16", "float32", "float64", "int16", "int32", "int64"]
                )
                if "float" in dtype_choice:
                    arr = np.array(
                        [rng.uniform(-10.0, 10.0) for _ in range(n_samples)],
                        dtype=dtype_choice,
                    )
                else:
                    arr = np.array(
                        [rng.randint(-50, 50) for _ in range(n_samples)],
                        dtype=dtype_choice,
                    )
                data_dict[col_name] = arr

            X = pd.DataFrame(data_dict)
            selector = DummySelector(mask=mask)
            selector.fit(X)

            if hasattr(selector, "set_output"):
                out_config = rng.choice(["pandas", "pandas", "default"])
                selector.set_output(transform=out_config)

            items.append((selector, (X,), {}))
        else:
            # Ordinary numpy arrays or sparse CSR matrices
            data_type = rng.choice(["float64", "float32", "int32", "int64"])
            X_arr = np.array(
                [
                    [rng.uniform(-10.0, 10.0) for _ in range(n_features)]
                    for _ in range(n_samples)
                ],
                dtype=data_type,
            )
            if rng.choice([False, True]):
                X_in = sparse.csr_matrix(X_arr)
            else:
                X_in = X_arr

            selector = DummySelector(mask=mask)
            selector.fit(X_in)
            items.append((selector, (X_in,), {}))

    return items

def make_inputs(rng, n):
    import numpy as np
    from matplotlib import path as mpath
    from matplotlib import collections as mcollections

    def make_random_path():
        num_vertices = rng.randint(2, 6)
        vertices = np.array([[rng.uniform(-10, 10), rng.uniform(-10, 10)] for _ in range(num_vertices)])
        return mpath.Path(vertices)

    items = []
    classes = [
        mcollections.Collection,
        mcollections.PathCollection,
        mcollections.LineCollection,
        mcollections.PolyCollection,
    ]

    for i in range(n):
        # Choose class to instantiate
        cls = rng.choice(classes)
        if cls is mcollections.Collection:
            inst = mcollections.Collection()
        elif cls is mcollections.PathCollection:
            init_paths = [make_random_path() for _ in range(rng.randint(0, 3))]
            inst = mcollections.PathCollection(paths=init_paths)
        elif cls is mcollections.LineCollection:
            segments = [[[rng.uniform(0, 1), rng.uniform(0, 1)], [rng.uniform(0, 1), rng.uniform(0, 1)]]
                        for _ in range(rng.randint(0, 3))]
            inst = mcollections.LineCollection(segments=segments)
        elif cls is mcollections.PolyCollection:
            verts = [[[rng.uniform(0, 1), rng.uniform(0, 1)] for _ in range(3)]]
            inst = mcollections.PolyCollection(verts=verts)

        # Generate paths argument
        path_count = rng.choice([0, 1, 2, 4])
        paths = [make_random_path() for _ in range(path_count)]

        # Variations in paths container type
        container_type = rng.choice(["list", "tuple", "generator", "array"])
        if container_type == "list":
            arg_paths = paths
        elif container_type == "tuple":
            arg_paths = tuple(paths)
        elif container_type == "generator":
            arg_paths = (p for p in paths)
        else:
            arg_paths = np.array(paths, dtype=object)

        if rng.random() < 0.2:
            kwargs = {'paths': arg_paths}
            args = ()
        else:
            kwargs = {}
            args = (arg_paths,)

        items.append((inst, args, kwargs))

    return items

import numpy as np
import astropy.units as u


class DuckQuantity(np.lib.mixins.NDArrayOperatorsMixin):
    def __init__(self, quantity):
        self.ndarray = quantity

    @property
    def unit(self):
        return self.ndarray.unit

    def __array_ufunc__(self, function, method, *inputs, **kwargs):
        unwrapped = [
            inp.ndarray if isinstance(inp, DuckQuantity) else inp for inp in inputs
        ]
        for inp in unwrapped:
            if isinstance(inp, np.ndarray):
                res = inp.__array_ufunc__(function, method, *unwrapped, **kwargs)
                if res is not NotImplemented:
                    return DuckQuantity(res)
        return NotImplemented


class IncompatibleDuck(np.lib.mixins.NDArrayOperatorsMixin):
    def __init__(self, unit):
        self._unit = unit

    @property
    def unit(self):
        return self._unit

    def __array_ufunc__(self, function, method, *inputs, **kwargs):
        return NotImplemented


def make_inputs(rng, n):
    Quantity = module.Quantity
    units_list = [
        u.m,
        u.mm,
        u.km,
        u.s,
        u.deg,
        u.rad,
        u.kg,
        u.m / u.s,
        u.dimensionless_unscaled,
    ]
    ufuncs_binary = [np.add, np.subtract, np.multiply, np.divide, np.greater]
    ufuncs_unary = [np.sin, np.cos, np.exp, np.negative, np.abs]

    items = []
    for i in range(n):
        # Half standard calls, half duck-type / incompatible unit conversion cases
        is_issue_case = i % 2 == 1

        if is_issue_case:
            # Trigger conversion or handling on duck-types where converter fails on the duck object
            # or converters_and_unit fails/raises TypeError/ValueError
            q_val = rng.uniform(0.1, 10.0)
            u1 = rng.choice(units_list)
            q = Quantity(q_val, u1)

            # Variant 1: Duck with compatible unit (like m and mm) where converter(DuckArray) raises ValueError in _condition_arg
            # Variant 2: Duck with incompatible unit
            # Variant 3: Duck with custom __array_ufunc__ returning NotImplemented
            duck_type_choice = rng.choice([1, 2, 3])
            func = rng.choice(ufuncs_binary)
            method = "__call__"

            if duck_type_choice == 1:
                # Same physical dimension, different scale (needs converter!)
                equiv_units = [
                    (u.m, u.mm),
                    (u.m, u.km),
                    (u.deg, u.rad),
                    (u.s, u.hour),
                    (u.kg, u.g),
                ]
                base_u1, base_u2 = rng.choice(equiv_units)
                if rng.random() < 0.5:
                    q = Quantity(rng.uniform(1.0, 5.0), base_u1)
                    duck_val = Quantity(rng.uniform(1.0, 5.0), base_u2)
                else:
                    q = Quantity(rng.uniform(1.0, 5.0), base_u2)
                    duck_val = Quantity(rng.uniform(1.0, 5.0), base_u1)
                duck = DuckQuantity(duck_val)
                args = (func, method, q, duck)
            elif duck_type_choice == 2:
                # Incompatible unit duck
                u2 = u.s if u1.is_equivalent(u.m) else u.m
                duck = IncompatibleDuck(u2)
                args = (func, method, q, duck)
            else:
                # Non-unit custom duck
                duck = DuckQuantity(
                    Quantity(rng.uniform(1.0, 5.0), rng.choice(units_list))
                )
                args = (func, method, q, duck)

            kwargs = {}
            items.append((q, args, kwargs))
        else:
            # Ordinary cases: simple valid or standard numpy Quantity ufunc operations
            u1 = rng.choice(units_list)
            shape_choice = rng.choice([(), (3,), (2, 2)])
            if shape_choice == ():
                val = rng.uniform(-10, 10)
            else:
                val = np.array([rng.uniform(-10, 10) for _ in range(np.prod(shape_choice))]).reshape(
                    shape_choice
                )

            q = Quantity(val, u1)
            ufunc_type = rng.choice(["unary", "binary"])
            method = rng.choice(["__call__", "reduce"] if shape_choice != () else ["__call__"])

            if ufunc_type == "unary" or method == "reduce":
                if method == "reduce":
                    func = np.add
                    args = (func, method, q)
                else:
                    func = rng.choice(ufuncs_unary)
                    args = (func, method, q)
            else:
                func = rng.choice(ufuncs_binary)
                # Second operand can be scalar, array, or another Quantity
                op2_kind = rng.choice(["quantity", "scalar", "array"])
                if op2_kind == "quantity":
                    # either same or compatible unit
                    u2 = u1 if rng.random() < 0.7 else rng.choice(units_list)
                    op2 = Quantity(rng.uniform(1, 5), u2)
                elif op2_kind == "scalar":
                    op2 = rng.uniform(1, 5)
                else:
                    op2 = np.ones(shape_choice) if shape_choice else np.array([2.0])

                args = (func, method, q, op2)

            kwargs = {}
            items.append((q, args, kwargs))

    return items

import matplotlib.pyplot as plt
from seaborn._core.scales import Continuous, Nominal


def make_inputs(rng, n):
    items = []
    plot_cls = getattr(module, "Plot")

    for i in range(n):
        # Create a fresh figure and Plotter instance
        fig = plt.figure()
        plotter = target_class(pyplot=False, theme={})
        plotter._figure = fig

        # Create one or two subplots
        num_subplots = rng.choice([1, 2])
        subplots_list = []
        for s_idx in range(num_subplots):
            ax = fig.add_subplot(1, num_subplots, s_idx + 1)
            # Enable grid to test grid disabling
            ax.grid(True)
            subplots_list.append(
                {
                    "ax": ax,
                    "x": f"x{s_idx}",
                    "y": f"y{s_idx}",
                }
            )
        plotter._subplots = subplots_list

        # Dummy Plot object
        p = plot_cls()
        # Ensure layout engine defaults work
        p._target = None if rng.random() > 0.3 else fig
        p._layout_spec = (
            {"engine": rng.choice(["tight", "constrained", None])}
            if rng.random() > 0.5
            else {}
        )
        p._limits = {}

        # Decide whether this is an ordinary case or nominal scale case
        is_nominal_case = i >= n // 2

        for sub in subplots_list:
            for axis in "xy":
                axis_key = sub[axis]
                ax = sub["ax"]

                # Populate ticks on the axis so get_major_ticks() has elements
                tick_count = rng.randint(2, 6)
                getattr(ax, f"set_{axis}ticks")(list(range(tick_count)))

                if is_nominal_case:
                    # In nominal case, assign Nominal scale to some/all axes
                    use_nominal = rng.random() > 0.2
                    if use_nominal:
                        plotter._scales[axis_key] = Nominal()
                    else:
                        plotter._scales[axis_key] = Continuous()

                    # Test whether explicit limits interact with nominal scaling
                    if rng.random() < 0.3:
                        if rng.random() < 0.5:
                            p._limits[axis_key] = (0, tick_count - 1)
                        else:
                            p._limits[axis_key] = (None, tick_count)
                else:
                    # Ordinary continuous scale case
                    plotter._scales[axis_key] = Continuous()
                    if rng.random() < 0.5:
                        p._limits[axis_key] = (rng.uniform(-1, 0), rng.uniform(1, 5))

        items.append((plotter, (p,), {}))

    return items

def make_inputs(rng, n):
    items = []
    app_names = ['auth', 'contenttypes', 'admin', 'sessions', 'myapp', 'users', 'blog']

    for i in range(n):
        # Create uninitialized instance
        receiver = target_class.__new__(target_class)

        # Generate models arg
        if rng.random() < 0.2:
            models_arg = None
        elif rng.random() < 0.2:
            models_arg = {}
        else:
            models_arg = {
                (rng.choice(app_names), f"model_{j}"): None
                for j in range(rng.randint(1, 3))
            }

        # Half ordinary (None or set), half non-set real_apps (triggering the assert in the fix)
        is_ordinary = (i % 2 == 0)

        if is_ordinary:
            # None or a set
            choice = rng.choice(['none', 'empty_set', 'set_of_apps'])
            if choice == 'none':
                real_apps = None
            elif choice == 'empty_set':
                real_apps = set()
            else:
                k = rng.randint(1, 4)
                real_apps = set(rng.sample(app_names, k))
        else:
            # Non-set iterables or falsy non-None / truthy non-set values
            choice = rng.choice([
                'list', 'tuple', 'dict', 'dict_keys', 'str', 'falsy_list', 'falsy_tuple'
            ])
            sample_apps = rng.sample(app_names, rng.randint(1, 3))
            if choice == 'list':
                real_apps = list(sample_apps)
