class _MockContext:
    def __init__(self, files):
        self.files = files
        self.orig_open = builtins.open

    def _mock_path(self, path_str):
        p = Path(path_str)
        p.is_file = lambda: str(path_str) in self.files
        return p

    def _mock_open(self, file, *args, **kwargs):
        if str(file) in self.files:
            return io.StringIO(self.files[str(file)])
        return self.orig_open(file, *args, **kwargs)

    def _query_cpu(self):
        with patch("pylint.lint.run.Path", side_effect=self._mock_path):
            with patch("builtins.open", side_effect=self._mock_open):
                return module._query_cpu()


