                w1 = Window(expression=Sum("id"), order_by=F("id").asc())
                w2 = Window(expression=RowNumber(), order_by=F("id").desc())
                query.add_annotation(w1, "win1")
                query.add_annotation(w2, "win2")
                agg1 = rng.choice(aggregates_pool)
                agg2 = rng.choice(aggregates_pool)
                exprs = {
                    "agg1": agg1("win1"),
                    "agg2": agg2("win2"),
                }
            elif window_style == "window_and_normal":
                w = Window(expression=Sum("id"), order_by=F("id").asc())
                query.add_annotation(w, "win_val")
                agg1 = rng.choice(aggregates_pool)
                agg2 = rng.choice(aggregates_pool)
                exprs = {
                    "normal_agg": agg1("id"),
                    "window_agg": agg2("win_val"),
                }

            items.append((query, (DEFAULT_DB_ALIAS, exprs), {}))

    return items

def make_inputs(rng, n):
    Mark = module.Mark
    MarkDecorator = module.MarkDecorator

    mark_names = ["foo", "bar", "baz", "skip", "xfail", "custom_mark"]

    def make_mark():
        name = rng.choice(mark_names)
        args = tuple(rng.randint(0, 10) for _ in range(rng.randint(0, 2)))
        kwargs = {f"k{i}": rng.choice(["a", "b", 1, None]) for i in range(rng.randint(0, 2))}
        m = Mark(name, args, kwargs)
        if rng.random() < 0.3:
            return MarkDecorator(m)
        return m

    items = []

    # First half: ordinary uses (functions, instances, simple objects, simple classes without inheritance)
    # Note: caller will test without passing consider_mro kwargs unless supported, so we provide args/kwargs carefully.
    # To be compatible with original version, args is (obj,), kwargs is {}
    n_issue = n // 2
    n_ord = n - n_issue

    for _ in range(n_ord):
        kind = rng.choice(["func", "object", "single_class", "no_mark"])
        if kind == "no_mark":
            def dummy():
                pass
            items.append((None, (dummy,), {}))
        elif kind == "func":
            def func():
                pass
            num_marks = rng.randint(1, 3)
            marks = [make_mark() for _ in range(num_marks)]
            func.pytestmark = marks if rng.random() < 0.8 else marks[0]
            items.append((None, (func,), {}))
        elif kind == "object":
            class PlainObj:
                pass
            inst = PlainObj()
            num_marks = rng.randint(0, 3)
            if num_marks > 0:
                marks = [make_mark() for _ in range(num_marks)]
                inst.pytestmark = marks if rng.random() < 0.8 else marks[0]
            items.append((None, (inst,), {}))
        elif kind == "single_class":
            class SingleClass:
                pass
            num_marks = rng.randint(1, 3)
            marks = [make_mark() for _ in range(num_marks)]
            SingleClass.pytestmark = marks if rng.random() < 0.8 else marks[0]
            items.append((None, (SingleClass,), {}))

    # Second half: class hierarchies (multiple inheritance, deep inheritance) where MRO matters
    for _ in range(n_issue):
        hierarchy_type = rng.choice(["diamond", "multiple_bases", "chain", "empty_child"])

        if hierarchy_type == "multiple_bases":
            class Base1:
                pass
            class Base2:
                pass
            class Derived(Base1, Base2):
                pass

            Base1.pytestmark = [make_mark() for _ in range(rng.randint(1, 2))]
            Base2.pytestmark = [make_mark() for _ in range(rng.randint(1, 2))]
            if rng.random() < 0.5:
                Derived.pytestmark = [make_mark() for _ in range(rng.randint(1, 2))]

            items.append((None, (Derived,), {}))

        elif hierarchy_type == "diamond":
            class Root:
                pass
            class Left(Root):
                pass
            class Right(Root):
                pass
            class Bottom(Left, Right):
                pass

            if rng.random() < 0.5:
                Root.pytestmark = [make_mark()]
            Left.pytestmark = [make_mark() for _ in range(rng.randint(1, 2))]
            Right.pytestmark = [make_mark() for _ in range(rng.randint(1, 2))]
            if rng.random() < 0.5:
                Bottom.pytestmark = [make_mark()]

            items.append((None, (Bottom,), {}))

        elif hierarchy_type == "chain":
            class GrandParent:
                pass
            class Parent(GrandParent):
                pass
            class Child(Parent):
                pass

            GrandParent.pytestmark = [make_mark()]
            if rng.random() < 0.7:
                Parent.pytestmark = [make_mark()]
            if rng.random() < 0.7:
                Child.pytestmark = [make_mark()]

            target = rng.choice([Child, Parent])
            items.append((None, (target,), {}))

        elif hierarchy_type == "empty_child":
            class BaseA:
                pass
            class BaseB:
                pass
            class EmptyChild(BaseA, BaseB):
                pass

            BaseA.pytestmark = [make_mark()]
            BaseB.pytestmark = [make_mark()]

            items.append((None, (EmptyChild,), {}))

    return items

def make_inputs(rng, n):
    Mark = module.Mark

    def create_mark(name_suffix=""):
        name = rng.choice(["skip", "xfail", "slow", "custom", "foo", "bar"]) + name_suffix
        args = tuple(rng.choice([1, "a", (1, 2), None]) for _ in range(rng.randint(0, 2)))
        kwargs = {f"k{i}": rng.randint(0, 10) for i in range(rng.randint(0, 2))}
        return Mark(name, args, kwargs)

    items = []
    for i in range(n):
        mark_to_store = create_mark(str(i))

        # Half ordinary (functions, simple objects, classes with no inheritance)
        # Half inheritance cases (classes inheriting from classes that have pytestmark)
        if rng.random() < 0.5:
            obj_type = rng.choice(["func", "class", "instance"])
            if obj_type == "func":
                def func():
                    pass
                if rng.random() < 0.5:
                    func.pytestmark = [create_mark("prev") for _ in range(rng.randint(1, 3))]
                elif rng.random() < 0.2:
                    func.pytestmark = create_mark("single")
                target = func
            elif obj_type == "instance":
                class SimpleObj:
                    pass
                target = SimpleObj()
                if rng.random() < 0.5:
                    target.pytestmark = [create_mark("prev") for _ in range(rng.randint(1, 3))]
            else:
                class StandaloneClass:
                    pass
                if rng.random() < 0.5:
                    StandaloneClass.pytestmark = [create_mark("prev") for _ in range(rng.randint(1, 3))]
                elif rng.random() < 0.2:
                    StandaloneClass.pytestmark = create_mark("single")
                target = StandaloneClass
        else:
            # Inheritance cases where consider_mro makes a difference
            # In original code, store_mark(SubClass, mark) called get_unpacked_marks(SubClass)
            # which looked up getattr(SubClass, "pytestmark"), inheriting parent's marks!
            # With the fix, store_mark uses consider_mro=False, so parent marks aren't copied onto SubClass.
            case = rng.choice(["single_inheritance", "multiple_inheritance", "deep_inheritance"])
            if case == "single_inheritance":
                class Parent:
                    pytestmark = [create_mark("parent") for _ in range(rng.randint(1, 3))]

                class Child(Parent):
                    pass

                if rng.random() < 0.4:
                    # Child already has its own marks directly
                    Child.pytestmark = [create_mark("child") for _ in range(rng.randint(1, 2))]
                target = Child

            elif case == "multiple_inheritance":
                class BaseA:
                    pytestmark = [create_mark("baseA")]

                class BaseB:
                    pytestmark = [create_mark("baseB")]

                class MultiChild(BaseA, BaseB):
                    pass

                if rng.random() < 0.4:
                    MultiChild.pytestmark = [create_mark("child")]
                target = MultiChild

            else:
                class GrandParent:
                    pytestmark = [create_mark("gp")]

                class Intermediate(GrandParent):
                    pass

                class DeepChild(Intermediate):
                    pass

                if rng.random() < 0.3:
                    Intermediate.pytestmark = [create_mark("inter")]
                if rng.random() < 0.3:
                    DeepChild.pytestmark = [create_mark("child")]
                target = DeepChild

        items.append((None, (target, mark_to_store), {}))

    return items
